        nHeight = pF->GetHeight();
    nPos2 /= nHeight;                       // ... now in % (rounded)
    if( nPos2 > MAX_ESC_POS )
        nPos2 = MAX_ESC_POS;
    if( nPos2 < -MAX_ESC_POS )
        nPos2 = -MAX_ESC_POS;
    SvxEscapementItem aEs( static_cast<short>(nPos2), 100, RES_CHRATR_ESCAPEMENT );
